import os
import psycopg
from mem0 import Memory

# 1. Khoi tao Mem0 OSS v3 chay trong VPC rieng, luu vector tren Qdrant
MEM0_CONFIG = {
    "llm": {
        "provider": "openai",
        "config": {"model": "gpt-4o-mini", "temperature": 0.1},
    },
    "vector_store": {
        "provider": "qdrant",
        "config": {
            "host": os.getenv("QDRANT_HOST", "127.0.0.1"),
            "port": 6333,
            "collection_name": "cskh_soft_memories",
        },
    },
}
memory = Memory.from_config(MEM0_CONFIG)

def scoped_user_key(tenant_id: str, canonical_contact_id: str) -> str:
    # Khoa cach ly tuyet doi theo Dai ly F1 / Doanh nghiep, khong dung SDT tran
    return f"tenant_{tenant_id}:contact_{canonical_contact_id}"

def fetch_authoritative_crm_state(tenant_id: str, contact_id: str) -> dict:
    """Nguon su that duy nhat cho gia ban, coc, pipeline 8 nac va cong no."""
    with psycopg.connect(os.environ["DATABASE_URL"]) as conn:
        with conn.cursor() as cur:
            # Cuong che Postgres FORCE ROW LEVEL SECURITY cho dung tenant
            cur.execute("SET LOCAL app.current_tenant_id = %s", (tenant_id,))
            cur.execute(
                """
                SELECT c.pipeline_stage, u.unit_code, u.listed_price_vnd, u.lock_status
                FROM crm_deals c
                LEFT JOIN unit_inventory u ON u.id = c.unit_id
                WHERE c.contact_id = %s
                LIMIT 1
                """,
                (contact_id,),
            )
            row = cur.fetchone()
    if not row:
        return {"pipeline_stage": "Lead Mới", "unit": None}
    return {
        "pipeline_stage": row[0],
        "unit_code": row[1],
        "listed_price_vnd": row[2],
        "lock_status": row[3],
    }

def build_cskh_prompt_context(tenant_id: str, contact_id: str, user_msg: str) -> dict:
    u_key = scoped_user_key(tenant_id, contact_id)
    # Doc ky uc mem (so thich, gu can ho, gio tien nghe may) - ~35ms
    soft_res = memory.search(
        query=user_msg,
        filters={"user_id": u_key},
        limit=5,
    )
    soft_memories = [item["memory"] for item in soft_res.get("results", [])]
    # Doc trang thai giao dich that tu PostgreSQL FORCE RLS
    crm_truth = fetch_authoritative_crm_state(tenant_id, contact_id)
    return {"soft_preferences": soft_memories, "crm_authoritative": crm_truth}

def async_record_soft_turn(tenant_id: str, contact_id: str, messages: list[dict]):
    """Chay o BullMQ/worker nen sau khi da gui tin nhan cho khach."""
    u_key = scoped_user_key(tenant_id, contact_id)
    memory.add(
        messages,
        user_id=u_key,
        metadata={"tenant_id": tenant_id, "memory_class": "soft_preference_only"},
    )

def forget_customer_memory(tenant_id: str, contact_id: str):
    """Quyen xoa du lieu theo yeu cau khach hang."""
    return memory.delete_all(user_id=scoped_user_key(tenant_id, contact_id))
